export type { CommandModalHandler } from "@easy-shadcn/command-modal";
export type { AlertModalProps } from "./alert-modal";
export type { ModalProps } from "./modal";

import CommandModal from "@easy-shadcn/command-modal";
import { AlertModal as OriginalAlertModal } from "./alert-modal";
import AlertCommandModal from "./alert-modal-helper";
import { Modal as OriginalModal } from "./modal";

export const AlertModal: typeof OriginalAlertModal & typeof AlertCommandModal =
  Object.assign(OriginalAlertModal, AlertCommandModal);

export const Modal: typeof OriginalModal & typeof CommandModal = Object.assign(
  OriginalModal,
  CommandModal
);

"use client";

import type { ClassValue } from "class-variance-authority/types";
import type React from "react";
import { type ReactElement, type ReactNode, useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";

export interface ModalProps {
  afterClose?: () => void;
  bodyClassName?: ClassValue;
  children?: ReactNode;

  className?: ClassValue;
  defaultOpen?: boolean;
  description?: ReactNode;
  descriptionClassName?: ClassValue;
  footer?: ReactNode;
  footerClassName?: ClassValue;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
  showCloseButton?: boolean;

  title?: ReactNode;
  titleClassName?: ClassValue;
  trigger?: ReactElement;
}

export const Modal: React.FC<ModalProps> = ({
  open,
  defaultOpen,
  onOpenChange,
  title,
  titleClassName,
  description,
  descriptionClassName,
  children,
  bodyClassName,
  className,
  footer,
  footerClassName,
  trigger,
  showCloseButton = true,
  afterClose,
}) => {
  const [internalOpen, setInternalOpen] = useState(defaultOpen ?? false);
  const currentOpen = open === undefined ? internalOpen : open;

  const handleOpenChange = (next: boolean) => {
    if (open === undefined) {
      setInternalOpen(next);
    }
    onOpenChange?.(next);
  };

  return (
    <Dialog
      onOpenChange={handleOpenChange}
      onOpenChangeComplete={(o) => {
        if (!o) {
          afterClose?.();
        }
      }}
      open={currentOpen}
    >
      {trigger && <DialogTrigger render={trigger} />}
      <DialogContent
        className={cn(className)}
        showCloseButton={showCloseButton}
      >
        {(title || description) && (
          <DialogHeader>
            {title && (
              <DialogTitle className={cn(titleClassName)}>{title}</DialogTitle>
            )}
            {description && (
              <DialogDescription
                className={cn(descriptionClassName)}
                render={<div />}
              >
                {description}
              </DialogDescription>
            )}
          </DialogHeader>
        )}
        {children && (
          <div className={cn("text-sm", bodyClassName)}>{children}</div>
        )}
        {footer && (
          <DialogFooter className={cn(footerClassName)}>{footer}</DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
};

"use client";

import type { ClassValue } from "class-variance-authority/types";
import type React from "react";
import {
  type ComponentProps,
  type ReactElement,
  type ReactNode,
  useState,
} from "react";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { cn } from "@/lib/utils";
import { AsyncButton } from "../async-button";

export interface AlertModalProps {
  afterClose?: () => void;
  cancelProps?: ComponentProps<typeof AsyncButton>;

  cancelText?: ReactNode;
  confirmProps?: ComponentProps<typeof AsyncButton>;
  confirmText?: ReactNode;
  defaultOpen?: boolean;
  description?: ReactNode;
  descriptionClassName?: ClassValue;
  footer?: ReactNode;
  footerClassName?: ClassValue;
  onCancel?: () => void | Promise<void>;
  onConfirm?: () => void | Promise<void>;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;

  title?: ReactNode;
  titleClassName?: ClassValue;

  trigger?: ReactElement;
}

export const AlertModal: React.FC<AlertModalProps> = ({
  open,
  defaultOpen,
  onOpenChange,
  title,
  titleClassName,
  description,
  descriptionClassName,
  trigger,
  footer,
  footerClassName,
  cancelText,
  onCancel,
  cancelProps,
  confirmText,
  onConfirm,
  confirmProps,
  afterClose,
}) => {
  const [internalOpen, setInternalOpen] = useState(defaultOpen ?? false);
  const currentOpen = open === undefined ? internalOpen : open;

  const handleOpenChange = (next: boolean) => {
    if (open === undefined) {
      setInternalOpen(next);
    }
    onOpenChange?.(next);
  };

  const close = () => handleOpenChange(false);

  return (
    <AlertDialog
      onOpenChange={handleOpenChange}
      onOpenChangeComplete={(o) => {
        if (!o) {
          afterClose?.();
        }
      }}
      open={currentOpen}
    >
      {trigger && <AlertDialogTrigger render={trigger} />}
      <AlertDialogContent>
        {(title || description) && (
          <AlertDialogHeader>
            {title && (
              <AlertDialogTitle className={cn(titleClassName)}>
                {title}
              </AlertDialogTitle>
            )}
            {description && (
              <AlertDialogDescription
                className={cn(descriptionClassName)}
                render={<div />}
              >
                {description}
              </AlertDialogDescription>
            )}
          </AlertDialogHeader>
        )}
        <AlertDialogFooter className={cn(footerClassName)}>
          {footer ?? (
            <>
              <AsyncButton
                onClick={async () => {
                  await onCancel?.();
                  close();
                }}
                variant="outline"
                {...cancelProps}
              >
                {cancelText ?? "Cancel"}
              </AsyncButton>
              <AsyncButton
                onClick={async () => {
                  await onConfirm?.();
                  close();
                }}
                {...confirmProps}
              >
                {confirmText ?? "OK"}
              </AsyncButton>
            </>
          )}
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
};

import CommandModal from "@easy-shadcn/command-modal";
import { AlertModal, type AlertModalProps } from "./alert-modal";

// TODO: modalProps will cover props

const alert = (
  props: Omit<
    AlertModalProps,
    "open" | "onOpenChange" | "cancelProps" | "onCancel" | "cancelText"
  >
) => {
  const AlertCommandModal = CommandModal.create(() => {
    const { modalProps, resolve } = CommandModal.useModal();
    return (
      <AlertModal
        {...props}
        {...modalProps}
        cancelProps={{
          className: "hidden",
        }}
        onConfirm={async () => {
          await props.onConfirm?.();
          resolve();
        }}
      />
    );
  });

  return CommandModal.show(AlertCommandModal);
};

const confirm = (props: Omit<AlertModalProps, "open" | "onOpenChange">) => {
  const AlertCommandModal = CommandModal.create(() => {
    const { modalProps, resolve, reject } = CommandModal.useModal();

    return (
      <AlertModal
        {...props}
        {...modalProps}
        onCancel={async () => {
          await props.onCancel?.();
          reject();
        }}
        onConfirm={async () => {
          await props.onConfirm?.();
          resolve();
        }}
      />
    );
  });

  return CommandModal.show(AlertCommandModal);
};

export default {
  alert,
  confirm,
};
